    assert(await evaluate(`[...document.querySelectorAll('[data-question]')].every(x=>{const q=[...NumberRevisionBank.questions,...NumberRevisionBank.problems].find(q=>q.id===x.dataset.question);return x.classList.contains('revision-item--working')===q.showWorking})`),'Working-space class drifted from the mark requirement');
