const alignedTicks=()=>evaluate(`(()=>{
    const article=document.querySelector(${JSON.stringify(ticket)}),field=article.querySelector('textarea'),f=field.getBoundingClientRect(),style=getComputedStyle(field);
    const ticks=[...article.querySelectorAll('.revision-mark-tick')].map(t=>t.getBoundingClientRect());
    const canvas=document.createElement('canvas').getContext('2d');canvas.font=style.font;
    return ticks.length===3 && ticks.slice(0,2).every((t,i)=>{
        const center=f.top+parseFloat(style.borderTopWidth)+parseFloat(style.paddingTop)+(i+.5)*parseFloat(style.lineHeight)-field.scrollTop;
        const end=f.left+parseFloat(style.paddingLeft)+canvas.measureText(field.value.split('\\n')[i]).width;
        return Math.abs(t.top+t.height/2-center)<2 && t.left>end && t.left<end+14;
    });
})()`);
