for(const mode of ['corrupt','shape','readBlocked','blocked']){
    const source=mode==='blocked'?`Storage.prototype.getItem=Storage.prototype.setItem=Storage.prototype.removeItem=function(){throw Error('blocked')}`
        :mode==='readBlocked'?`Storage.prototype.getItem=function(){throw Error('read blocked')}`
        :mode==='shape'?`Storage.prototype.getItem=function(){return '[]'}`:`Storage.prototype.getItem=function(){return '{bad json'}`;
    const {identifier}=await send('Page.addScriptToEvaluateOnNewDocument',{source},s);
    await go(base+'powersAndRoots/practiceRevisit.html');
    assert.equal(await evaluate(`document.querySelectorAll('[data-question]').length`),14);
    await type('[data-answer]','81');await click('[data-check]');
    assert(await evaluate(`document.querySelector('[data-answer]').classList.contains('is-accepted')`));
    assert(await evaluate(`!document.querySelector('[data-storage]').hidden`),mode+' storage problem was hidden');
    assert.match(await evaluate(`document.querySelector('[data-storage]').textContent`),mode==='blocked'?/cannot be saved/:/could not be read/,mode+' storage message was inaccurate');
    await send('Page.removeScriptToEvaluateOnNewDocument',{identifier},s);
}
await send('Emulation.setScriptExecutionDisabled',{value:true},s);
